const LIGHTS = ['#ff5a5a', '#ffd84a', '#5ad0ff', '#9aff6a'];
function tree(t, floor) {
  const x0 = w - 12;
  for (let y = 0; y < floor - 1; y++) {
    const half = Math.min(5, Math.floor(y * 0.8) + 1);
    for (let x = -half; x <= half; x++) {
