  const s = blinking(track(KEYS, u), t);
  const r = blinking(track(RK, u), t);
  whiteRoom(floor);
  dancer(r, at(r), ground, HIM);
  const d = dancer(s, at(s), ground, HER);
  if (u > 20.6) lights(Math.round(w / 2), Math.max(0, 40 * (1 - (u - 20.6) / 1.2)), floor);
